package io.github.long0823.tclviewer;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import org.videolan.libvlc.*;import org.videolan.libvlc.interfaces.IMedia;
public class FullscreenTest extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private static Object field(Object a,String name)throws Exception{Field f=a.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(a);}
 private void hideLogos(View view){if(view.getClass().getSimpleName().equals("LogoView")){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View child=group.getChildAt(i);if(child instanceof ImageView)child.setVisibility(View.INVISIBLE);if(child instanceof TextView){((TextView)child).setText("TV");child.setVisibility(View.VISIBLE);}}return;}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)hideLogos(group.getChildAt(i));}}
 public void onStart(){Bundle out=new Bundle();MainActivity a=null;try{getTargetContext().getSharedPreferences("MainActivity",0).edit().putBoolean("fill_video",false).commit();a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final MainActivity activity=a;ChannelConfig config=(ChannelConfig)field(a,"config");ChannelConfig.Channel selected=config.channels.get(0);for(ChannelConfig.Channel ch:config.channels)if(ch.sid==1040)selected=ch;Field current=MainActivity.class.getDeclaredField("current");current.setAccessible(true);current.set(a,selected);MediaPlayer player=(MediaPlayer)field(a,"player");LibVLC lib=(LibVLC)field(a,"lib");Media media=new Media(lib,android.net.Uri.fromFile(new File(a.getFilesDir(),"fixture.ts")));media.setHWDecoderEnabled(true,false);media.addOption(":program=1040");media.addOption(":input-repeat=20");runOnMainSync(()->{player.setVolume(0);player.setMedia(media);player.play();});media.release();Thread.sleep(2500);Method full=MainActivity.class.getDeclaredMethod("full",boolean.class);full.setAccessible(true);runOnMainSync(()->{try{full.invoke(activity,true);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(5000);View root=(View)field(a,"root"),video=(View)field(a,"video"),chrome=(View)field(a,"playerChrome"),surface=(View)field(a,"surface");int[] location=new int[2];video.getLocationOnScreen(location);boolean fills=location[0]==0&&location[1]==0&&video.getWidth()==root.getWidth()&&video.getHeight()==root.getHeight();boolean hidden=chrome.getVisibility()==View.GONE;boolean bars=Build.VERSION.SDK_INT<30||(!root.getRootWindowInsets().isVisible(WindowInsets.Type.statusBars())&&!root.getRootWindowInsets().isVisible(WindowInsets.Type.navigationBars()));out.putBoolean("video_fills_window",fills);out.putBoolean("controls_auto_hidden",hidden);out.putBoolean("system_bars_hidden",bars);out.putString("fullscreen_size",video.getWidth()+"x"+video.getHeight());Method show=MainActivity.class.getDeclaredMethod("showPlayerControls",boolean.class);show.setAccessible(true);runOnMainSync(()->{try{show.invoke(activity,true);}catch(Exception e){throw new RuntimeException(e);}});if(chrome.getVisibility()!=View.VISIBLE)throw new Exception("Controls did not show");Method fill=MainActivity.class.getDeclaredMethod("setVideoFill",boolean.class);fill.setAccessible(true);runOnMainSync(()->{try{fill.invoke(activity,true);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(2300);runOnMainSync(()->hideLogos(activity.getWindow().getDecorView()));Thread.sleep(150);try(FileOutputStream shot=new FileOutputStream(new File(activity.getFilesDir(),"fullscreen-test.png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,shot);}boolean cropped=surface.getWidth()>=video.getWidth()-1&&surface.getHeight()>=video.getHeight()-1;out.putBoolean("fill_covers_display",cropped);runOnMainSync(()->{try{full.invoke(activity,false);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(1200);boolean normal=((View)field(a,"tabs")).getVisibility()==View.VISIBLE&&((View)field(a,"header")).getVisibility()==View.VISIBLE;out.putBoolean("normal_ui_restored",normal);runOnMainSync(()->hideLogos(activity.getWindow().getDecorView()));Thread.sleep(150);try(FileOutputStream shot=new FileOutputStream(new File(activity.getFilesDir(),"portrait-test.png"))){getUiAutomation().takeScreenshot().compress(android.graphics.Bitmap.CompressFormat.PNG,100,shot);}IMedia currentMedia=player.getMedia();IMedia.Stats stats=currentMedia.getStats();out.putInt("rendered_frames",stats.displayedPictures);currentMedia.release();File logoDir=new File(a.getCacheDir(),"station-logos");int logoCount=0;for(int n=0;n<20;n++){File[] files=logoDir.listFiles((d,name)->name.endsWith(".png"));logoCount=files==null?0:files.length;if(logoCount>=11)break;Thread.sleep(500);}out.putInt("official_logos_cached",logoCount);if(!fills||!hidden||!bars||!cropped||!normal||stats.displayedPictures<10||logoCount<8)throw new Exception("Fullscreen, playback or logo assertion failed");out.putString("result","PASS");runOnMainSync(activity::finish);finish(-1,out);}catch(Throwable e){out.putString("result","FAIL "+e.toString());if(a!=null){final MainActivity activity=a;runOnMainSync(activity::finish);}finish(0,out);}}
}